// Drives the mic with a fake audio file in Chromium and reports what lands in the composer.
import { chromium } from "@playwright/test";
const [base, wav, shots] = process.argv.slice(2);
const browser = await chromium.launch({ args: ["--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream", `--use-file-for-fake-audio-capture=${wav}`, "--autoplay-policy=no-user-gesture-required"] });
const context = await browser.newContext({ baseURL: base, storageState: "e2e/.auth.json", permissions: ["microphone"], viewport: { width: 1280, height: 860 } });
const page = await context.newPage(); const t0 = Date.now(); const log = (...a) => console.log(((Date.now() - t0) / 1000).toFixed(1).padStart(5), ...a);
page.on("console", m => { if (m.type() === "error") log("console error:", m.text().slice(0, 200)); });
await page.goto("/ai"); await page.getByRole("button", { name: "Talk: record a voice message" }).first().click(); log("mic clicked");
const live = page.getByLabel("Voice message"); let last = "";
for (let i = 0; i < 26; i++) { await page.waitForTimeout(500); const text = (await live.textContent().catch(() => "")) ?? ""; if (text !== last) { log("live:", JSON.stringify(text.slice(0, 160))); last = text; } if (i === 8) await page.screenshot({ path: `${shots}/mic-recording.png` }); }
await page.getByRole("button", { name: "Done: put the words in the box to edit" }).click();
await page.waitForTimeout(800); log("box:", JSON.stringify(await page.locator("textarea").first().inputValue()));
await page.screenshot({ path: `${shots}/mic-done.png` }); await browser.close();

"use client";

import { useEffect, useRef, useState } from "react";
import { Loader2, Mic, MicOff, PhoneOff, Send, X } from "lucide-react";
import { IouCard } from "@/components/iou-card";
import { useVoiceCall } from "@/lib/ai/use-voice-call";
import type { ChatAnswer } from "@/lib/ai/use-chat-request";

/** The orb follows whoever is talking; it holds still when reduced motion is asked for. */
function Orb({ levels, state }: { levels: () => { mic: number; moneo: number }; state: "connecting" | "listening" | "thinking" | "speaking" | "idle" }) {
  const orb = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    let frame = 0, smooth = 0;
    const tick = () => {
      const { mic, moneo } = levels();
      smooth += (Math.max(mic, moneo) - smooth) * 0.25;
      orb.current?.style.setProperty("--level", smooth.toFixed(3));
      frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [levels]);
  const tone = state === "speaking" ? "from-lime to-brand" : state === "thinking" ? "from-ai to-ai-border" : "from-ai-border to-lime";
  return <div aria-hidden="true" className="relative grid size-40 place-items-center sm:size-48">
    <div className={`absolute inset-0 rounded-full bg-gradient-to-br ${tone} opacity-25 blur-2xl transition-colors duration-500`} />
    <div ref={orb} style={{ transform: "scale(calc(1 + var(--level, 0) * 0.35))" }}
      className={`size-28 rounded-full bg-gradient-to-br ${tone} shadow-[0_0_60px_-10px] shadow-ai/50 transition-colors duration-500 sm:size-32 ${state === "thinking" || state === "connecting" ? "motion-safe:animate-pulse" : ""}`} />
  </div>;
}

/** A live voice call with Moneo: speak or type, see captions and running tasks, and tap the cards it makes. */
export function VoiceCall({ conversationId, onAnswer, onEnded, onClose }: { conversationId: string; onAnswer: (question: string, answer: ChatAnswer) => void; onEnded: () => void; onClose: () => void }) {
  const call = useVoiceCall(conversationId, onAnswer, onEnded);
  const [text, setText] = useState("");
  const captions = useRef<HTMLDivElement>(null);
  useEffect(() => { captions.current?.scrollTo({ top: captions.current.scrollHeight }); }, [call.captions]);
  const last = call.captions.at(-1);
  const state = call.status === "connecting" ? "connecting" : call.status !== "live" ? "idle" : last?.role === "assistant" && !call.thinking ? "speaking" : call.thinking ? "thinking" : "listening";
  const label = { connecting: "Connecting…", listening: call.muted ? "Muted" : "Listening", thinking: "Working on it", speaking: "Moneo is talking", idle: call.status === "ended" ? "Call ended" : "Call failed" }[state];
  const running = call.tasks.filter(task => task.status === "running");
  const round = "grid size-14 place-items-center rounded-full transition-colors focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ai";

  return <section role="dialog" aria-modal="true" aria-label="Voice call with Moneo" className="fixed inset-0 z-50 flex flex-col bg-background lg:sticky lg:top-19 lg:z-auto lg:h-[calc(100dvh-4.75rem)]">
    <header className="flex items-center justify-between gap-3 border-b border-border px-4 py-3 sm:px-8">
      <p className="font-display text-lg font-semibold">Call with Moneo</p>
      <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground">{state === "connecting" && <Loader2 className="size-4 motion-safe:animate-spin" aria-hidden="true" />}{label}</p>
    </header>
    <div className="mx-auto flex min-h-0 w-full max-w-[820px] flex-1 flex-col gap-4 overflow-y-auto px-4 py-6 sm:px-8">
      <div className="flex flex-col items-center gap-2"><Orb levels={call.levels} state={state} /></div>
      {call.error && <p role="alert" className="rounded-lg border border-danger/40 px-3 py-2 text-sm text-danger">{call.error}</p>}
      <div ref={captions} aria-live="polite" aria-label="Live captions" className="max-h-48 space-y-2 overflow-y-auto text-[15px] leading-relaxed">
        {!call.captions.length && call.status === "live" && <p className="text-center text-muted-foreground">Say hi, ask about your money, or tell Moneo what you spent.</p>}
        {call.captions.slice(-8).map(caption => <p key={caption.id} className={caption.role === "user" ? "ml-auto w-fit max-w-[85%] rounded-2xl bg-muted px-3 py-1.5" : "max-w-[90%]"}>
          <span className="sr-only">{caption.role === "user" ? "You: " : "Moneo: "}</span>{caption.text}</p>)}
      </div>
      {call.tasks.length > 0 && <div>
        <p className="eyebrow pb-1.5">{running.length ? `Working on ${running.length}` : "Done"}</p>
        <ul className="space-y-1.5" aria-label="Tasks">
          {call.tasks.slice(-6).map(task => <li key={task.requestId} className="flex items-center gap-2 rounded-xl border border-border bg-card px-3 py-2 text-sm">
            {task.status === "running" ? <Loader2 className="size-4 shrink-0 text-ai motion-safe:animate-spin" aria-hidden="true" /> : <span aria-hidden="true" className={`size-2 shrink-0 rounded-full ${task.status === "done" ? "bg-success" : task.status === "failed" ? "bg-danger" : "bg-subtle"}`} />}
            <span className="min-w-0 flex-1"><span className="block truncate">{task.text}</span><span className="block text-xs text-muted-foreground">{task.step}</span></span>
            {task.status === "running" && <button type="button" onClick={() => void call.cancel(task.requestId)} aria-label={`Stop “${task.text}”`} className="rounded-md p-1.5 text-muted-foreground hover:bg-muted hover:text-foreground"><X className="size-4" aria-hidden="true" /></button>}
          </li>)}
        </ul>
      </div>}
      {call.cards.length > 0 && <div aria-label="Cards to review" role="region">
        <p className="eyebrow">Tap to save · nothing is saved until you do</p>
        {call.cards.map(id => <IouCard key={id} id={id} />)}
      </div>}
    </div>
    <footer className="border-t border-border px-4 pt-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] sm:px-8">
      <form onSubmit={event => { event.preventDefault(); call.typed(text); setText(""); }} className="mx-auto flex max-w-[820px] items-center gap-2">
        <label className="sr-only" htmlFor="call-text">Type to Moneo</label>
        <input id="call-text" value={text} onChange={event => setText(event.target.value)} maxLength={4000} placeholder="Or type here…" autoComplete="off"
          className="min-w-0 flex-1 rounded-full border border-border bg-card px-4 py-2.5 text-sm focus:border-muted-foreground/40 focus:outline-none" />
        <button aria-label="Send" disabled={!text.trim()} className="grid size-10 place-items-center rounded-full bg-primary text-primary-foreground disabled:opacity-40"><Send className="size-4" aria-hidden="true" /></button>
      </form>
      <div className="mt-3 flex items-center justify-center gap-6">
        <button type="button" onClick={call.toggleMute} aria-pressed={call.muted} aria-label={call.muted ? "Unmute" : "Mute"} disabled={call.status !== "live"}
          className={`${round} ${call.muted ? "bg-foreground text-background" : "bg-muted hover:bg-accent"} disabled:opacity-40`}>{call.muted ? <MicOff className="size-5" aria-hidden="true" /> : <Mic className="size-5" aria-hidden="true" />}</button>
        <button type="button" onClick={onClose} aria-label={call.status === "live" || call.status === "connecting" ? "End call" : "Close"} className={`${round} bg-danger text-white hover:opacity-90`}><PhoneOff className="size-5" aria-hidden="true" /></button>
      </div>
    </footer>
  </section>;
}
"use client";

import dynamic from "next/dynamic";
import { ChevronRight, LoaderCircle, Phone } from "lucide-react";
import { IouCard } from "@/components/iou-card";
import type { CallCard } from "@/lib/ai/voice-call-history";

const AiMessage = dynamic(() => import("./ai-message").then(module => module.AiMessage), {
  loading: () => <div className="h-5 w-2/3 animate-pulse rounded bg-muted" aria-hidden="true" />,
});

export function callDuration(seconds: number) {
  const minutes = Math.floor(seconds / 60);
  return minutes ? `${minutes} min${seconds % 60 ? ` ${seconds % 60} s` : ""}` : `${seconds} s`;
}

const STATUS = { running: "still running", completed: "finished afterwards", failed: "failed", canceled: "stopped" } as const;
const fold = "group rounded-xl border border-border px-3 py-2 text-sm";
const foldTitle = "flex cursor-pointer list-none items-center gap-1.5 text-xs font-medium text-muted-foreground hover:text-foreground [&::-webkit-details-marker]:hidden";

/** A finished voice call in the chat: summary, cards, anything left running, the requests it made and the full transcript. */
export function VoiceCallCard({ call, createdAt }: { call: CallCard; createdAt: string }) {
  const bullets = call.summary?.split("\n").map(line => line.replace(/^-\s*/, "")).filter(Boolean) ?? [];
  return <section aria-label="Voice call" className="space-y-3 rounded-2xl border border-border bg-card p-4">
    <p className="flex items-center gap-2 text-sm font-medium"><Phone className="size-4 text-ai" aria-hidden="true" />
      Voice call · {callDuration(call.durationSeconds)}<span className="font-normal text-muted-foreground">· <time dateTime={createdAt}>{new Date(createdAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}</time></span></p>
    {call.summaryStatus === "pending" && <p role="status" className="flex items-center gap-2 text-sm text-muted-foreground"><LoaderCircle className="size-4 motion-safe:animate-spin" aria-hidden="true" />Writing the summary…</p>}
    {bullets.length > 0 && <ul aria-label="Call summary" className="list-disc space-y-1 pl-5 text-[15px]">{bullets.map(line => <li key={line}>{line}</li>)}</ul>}
    {call.cards.length > 0 && <div role="region" aria-label="Cards from this call"><p className="eyebrow">Cards from this call</p>{call.cards.map(id => <IouCard key={id} id={id} />)}</div>}
    {call.unfinished.length > 0 && <div><p className="eyebrow pb-1">Still running when the call ended</p>
      <ul className="space-y-1 text-sm">{call.unfinished.map((task, index) => <li key={index}>{task.text} <span className="text-muted-foreground">· {STATUS[task.status]}</span></li>)}</ul></div>}
    {call.exchanges.length > 0 && <details className={fold}><summary className={foldTitle}>Requests from this call ({call.exchanges.filter(item => item.role === "user").length})<ChevronRight className="size-3.5 transition-transform group-open:rotate-90" aria-hidden="true" /></summary>
      <div className="mt-3 space-y-4">{call.exchanges.map(item => item.role === "user"
        ? <p key={item.id} className="ml-auto w-fit max-w-[85%] whitespace-pre-wrap rounded-2xl bg-input px-3.5 py-2">{item.content}</p>
        : <AiMessage key={item.id} content={item.content} />)}</div></details>}
    {call.transcript.length > 0 && <details className={fold}><summary className={foldTitle}>Full transcript<ChevronRight className="size-3.5 transition-transform group-open:rotate-90" aria-hidden="true" /></summary>
      <ol aria-label="Transcript" className="mt-3 space-y-2">{call.transcript.map((turn, index) => <li key={index}><span className="font-medium">{turn.role === "user" ? "You" : "Moneo"}: </span>{turn.text}</li>)}</ol></details>}
  </section>;
}
"use client";

import { useEffect, useRef, useState } from "react";
import { ArrowUp, Check, Mic, X } from "lucide-react";
import { useVoiceInput, VOICE_MAX_SECONDS } from "@/lib/ai/use-voice-input";

const clock = (ms: number) => { const seconds = Math.floor(ms / 1000); return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`; };

/**
 * The mic for a text input. A tap or a hold both start recording (on release, which Safari needs for the mic);
 * live words show over the input with a level meter, then Send sends them, Done puts them in the input to edit,
 * and Cancel or Escape discards them. Put it inside a `relative` form: the recording view covers that form.
 */
export function VoiceInput({ onSend, onDone, autoStart = false, disabled = false, compact = false }: {
  onSend: (text: string) => void; onDone: (text: string) => void; autoStart?: boolean; disabled?: boolean; compact?: boolean;
}) {
  const voice = useVoiceInput((action, text) => action === "send" ? onSend(text) : onDone(text));
  const { status, start } = voice;
  const mic = useRef<HTMLButtonElement>(null);
  const done = useRef<HTMLButtonElement>(null);
  const words = useRef<HTMLParagraphElement>(null);
  const wasActive = useRef(false);
  const [now, setNow] = useState(0);
  useEffect(() => { if (autoStart) void start(); }, [autoStart, start]);
  useEffect(() => {
    if (status === "recording") done.current?.focus();
    // Send and Cancel leave nothing focused; Done hands focus to the input itself.
    if (status === "idle" && wasActive.current && (!document.activeElement || document.activeElement === document.body)) mic.current?.focus();
    wasActive.current = status !== "idle";
    if (status !== "recording") return;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [status]);
  useEffect(() => { words.current?.scrollTo({ top: words.current.scrollHeight }); }, [voice.text]);

  const active = status !== "idle";
  const icon = compact ? "size-8" : "size-9";
  const action = "inline-flex h-9 items-center gap-1.5 rounded-xl px-3 text-sm font-medium disabled:opacity-40";
  const label = status === "starting" ? "Starting the microphone…" : status === "finishing" ? "Finishing…" : "Listening…";
  return <>
    <button ref={mic} type="button" onClick={() => void start()} onContextMenu={event => event.preventDefault()} disabled={disabled || active}
      aria-label="Talk: record a voice message" title="Talk" className={`flex shrink-0 touch-manipulation items-center justify-center rounded-lg text-muted-foreground select-none hover:bg-muted hover:text-foreground disabled:opacity-40 ${icon}`}>
      <Mic className="size-4" aria-hidden="true" /></button>
    {voice.error && !active && <p role="alert" className="absolute bottom-full left-0 mb-2 flex max-w-full items-center gap-2 rounded-lg border border-border bg-card px-3 py-1.5 text-xs text-danger shadow-sm">
      {voice.error}<button type="button" onClick={voice.cancel} aria-label="Dismiss" className="rounded p-0.5 text-muted-foreground hover:text-foreground"><X className="size-3" aria-hidden="true" /></button></p>}
    {active && <div role="group" aria-label="Voice message" onKeyDown={event => { if (event.key === "Escape") { event.preventDefault(); event.stopPropagation(); voice.cancel(); } }}
      className="absolute inset-0 z-10 flex min-h-28 flex-col gap-2 rounded-[inherit] border border-muted-foreground/60 bg-card p-2.5">
      <p ref={words} aria-live="polite" className={`min-h-0 flex-1 overflow-y-auto px-1 whitespace-pre-wrap ${compact ? "text-sm" : "text-[15px]"} ${voice.text ? "" : "text-muted-foreground"}`}>{voice.text || label}</p>
      <div className="flex items-center gap-2">
        <span className="flex h-5 items-center gap-0.5" aria-hidden="true">{[0.5, 0.8, 1, 0.8, 0.5].map((scale, index) =>
          <span key={index} className="w-1 rounded-full bg-danger transition-[height] duration-100" style={{ height: `${4 + Math.round(voice.level * scale * 16)}px` }} />)}</span>
        <span className="font-mono text-xs text-muted-foreground"><span className="sr-only">Recording </span>{clock(status === "recording" ? Math.max(0, now - voice.startedAt) : 0)} / {clock(VOICE_MAX_SECONDS * 1000)}</span>
        <span className="ml-auto" />
        <button type="button" onClick={() => { voice.cancel(); mic.current?.focus(); }} aria-label="Cancel and discard recording" className={`${action} text-muted-foreground hover:bg-muted hover:text-foreground`}><X className="size-4" aria-hidden="true" /><span className="max-sm:sr-only">Cancel</span></button>
        <button ref={done} type="button" onClick={() => void voice.done()} disabled={status !== "recording"} aria-label="Done: put the words in the box to edit" className={`${action} border border-input hover:bg-muted`}><Check className="size-4" aria-hidden="true" />Done</button>
        <button type="button" onClick={() => void voice.send()} disabled={status !== "recording"} aria-label="Send now" className={`${action} bg-primary text-primary-foreground hover:opacity-90`}><ArrowUp className="size-4" aria-hidden="true" />Send</button>
      </div>
    </div>}
  </>;
}
import { ArrowUp, FileText, LoaderCircle, Paperclip, Square, X } from "lucide-react";
import type { ChatAttachments } from "@/lib/ai/use-chat-attachments";
import { VoiceInput } from "./voice-input";

/** Spoken words added after whatever is already typed. */
export const withSpoken = (typed: string, spoken: string) => [typed.trim(), spoken].filter(Boolean).join(" ");

/**
 * Composer shared by the AI page and the Ask Moneo panel. Enter sends (or queues while busy), Shift+Enter adds a line.
 * With `voice`, a mic sends spoken words through `voice.onSend` or drops them into the box to edit.
 */
export function ChatComposer({ id, label, value, onChange, onSubmit, onStop, busy, disabled = false, placeholder, compact = false, busyText, attachments, voice }: {
  id: string; label: string; value: string; onChange: (value: string) => void; onSubmit: (event: React.FormEvent<HTMLFormElement>) => void;
  onStop: () => void; busy: boolean; disabled?: boolean; placeholder: string; compact?: boolean; busyText: string; attachments?: ChatAttachments;
  voice?: { onSend: (text: string) => void; autoStart?: boolean };
}) {
  const button = `flex items-center justify-center rounded-xl bg-primary text-primary-foreground hover:opacity-90 ${compact ? "size-9" : "size-11"}`;
  const files = attachments?.items ?? [];
  // A message can be just a photo or PDF; files still uploading or failed hold the send.
  const sendable = (value.trim() || attachments?.ready.length) && !attachments?.uploading && !files.some(item => item.error);
  return <form onSubmit={onSubmit} onPaste={event => { if (attachments && event.clipboardData.files.length) { event.preventDefault(); attachments.add(event.clipboardData.files); } }}
    className="relative rounded-2xl border border-input bg-card p-2.5 transition-colors focus-within:border-muted-foreground/60">
    {files.length > 0 && <ul className="flex flex-wrap gap-2 px-1 pb-2" aria-label="Attachments">{files.map(item => <li key={item.id} className={`flex max-w-56 items-center gap-2 rounded-lg border p-1.5 pr-1 text-xs ${item.error ? "border-danger text-danger" : "border-border"}`}>
      {/* eslint-disable-next-line @next/next/no-img-element -- private, signed or local blob images cannot go through the image optimizer */}
      {item.preview ? <img src={item.preview} alt="" className="size-8 shrink-0 rounded object-cover" /> : <FileText className="size-5 shrink-0" aria-hidden="true" />}
      <span className="min-w-0 truncate" title={item.error ?? item.name}>{item.error ?? item.name}</span>
      {!item.file && !item.error && <LoaderCircle className="size-3.5 shrink-0 animate-spin" aria-label="Uploading" />}
